WITH sales_by_state_month AS ( SELECT w.w_state, ((ws.ws_sold_date_sk / 100) % 100) AS sale_month, SUM(ws.ws_net_paid) AS monthly_net_paid, COUNT(DISTINCT wp.wp_type) AS distinct_page_types, AVG(hd.hd_vehicle_count) AS avg_vehicle_count FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk GROUP BY w.w_state, ((ws.ws_sold_date_sk / 100) % 100) ), cumulative_sales AS ( SELECT w_state, sale_month, monthly_net_paid, distinct_page_types, avg_vehicle_count, SUM(monthly_net_paid) OVER (PARTITION BY w_state ORDER BY sale_month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_paid FROM sales_by_state_month ) SELECT w_state, sale_month, monthly_net_paid, distinct_page_types, avg_vehicle_count, CASE WHEN monthly_net_paid > 100000 THEN 'High' WHEN monthly_net_paid > 50000 THEN 'Medium' ELSE 'Low' END AS month_net_paid_category, cumulative_net_paid, RANK() OVER (PARTITION BY w_state ORDER BY cumulative_net_paid DESC) AS month_cumulative_rank FROM cumulative_sales ORDER BY w_state, sale_month
